def pts(a, colors={8,9}):
 return {(r,c) for r,c in zip(*np.where(np.isin(a,list(colors))))}
Ain=pts(D1i[3:9,3:11]); Aout=pts(D1o[2:9,3:11]); Bin=pts(D1i[6:12,15:23]); Bout=pts(D1o[1:7,15:23])
def norm(p):
 mr=min(r for r,c in p);mc=min(c for r,c in p);return {(r-mr,c-mc) for r,c in p}
def trans(p,k):
 # transforms on normalized coordinates via coordinate formulas
 out=[]
 for r,c in p:
  if k==0: x,y=r,c
  if k==1: x,y=c,-r
  if k==2: x,y=-r,-c
  if k==3: x,y=-c,r
  if k==4: x,y=r,-c
  if k==5: x,y=-r,c
  if k==6: x,y=c,r
  if k==7: x,y=-c,-r
  out.append((x,y))
 return norm(out)
for name,p,q in [('A',Ain,Aout),('B',Bin,Bout)]:
 print(name, len(p),len(q),[k for k in range(8) if trans(p,k)==norm(q)])

